<script setup lang="ts">
import { ref } from 'vue'; import { Boxes, ArrowRight, ShieldCheck, Workflow, History } from 'lucide-vue-next'; import { post } from '../api'; import { session, router } from '../main'
const userName=ref('admin'),password=ref('Admin@123456'),error=ref(''),busy=ref(false)
async function login(){busy.value=true;error.value='';try{const r:any=await post('/auth/login',{userName:userName.value,password:password.value});session.token=r.token;session.user=r.user;localStorage.setItem('token',r.token);localStorage.setItem('user',JSON.stringify(r.user));router.push('/')}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="login-page"><div class="login-atmosphere"></div><section class="login-story"><div class="brand light"><span class="brand-mark"><Boxes :size="23"/></span><div><strong>铸剑台</strong><small>RELEASE FOUNDRY</small></div></div><div class="story-copy"><span class="eyebrow amber">SOFTWARE DELIVERY CONTROL</span><h1>让每一次发布<br/><em>有迹可循。</em></h1><p>从源码修订到运行进程，把复杂的发布链路收束成一条清晰、可靠、可回退的轨道。</p><div class="proofs"><span><Workflow/>分阶段可观测</span><span><ShieldCheck/>凭据安全保护</span><span><History/>完整版本历史</span></div></div><div class="build-number">PLATFORM / 01 · WINDOWS</div></section><section class="login-panel"><form @submit.prevent="login"><div class="form-intro"><span>欢迎回来</span><h2>登录控制台</h2><p>使用平台账户继续</p></div><label>用户名<input v-model="userName" autocomplete="username" autofocus/></label><label>密码<input v-model="password" type="password" autocomplete="current-password"/></label><div v-if="error" class="alert error">{{error}}</div><button class="btn primary wide" :disabled="busy">{{busy?'正在验证…':'进入平台'}}<ArrowRight :size="18"/></button><small class="login-note">首次运行：admin / Admin@123456<br/>登录后请立即修改初始密码</small></form></section></div></template>
